def stepper_turn(steps):
    for i in range(steps):
        for p, v in zip(coils, SEQ[i % 8]):
            p.value(v)
        time.sleep_ms(1)

def mpu_read():
    d = i2c.readfrom_mem(0x68, 0x3B, 6)
    def s(h, l):
        v = h << 8 | l
        return v - 65536 if v > 32767 else v
    return [round(s(d[i], d[i+1]) / 16384, 2) for i in (0, 2, 4)]

def hx_raw():
    t = time.ticks_ms()
    while hx_dt.value():                 # รอจนกว่า HX711 พร้อม
        if time.ticks_diff(time.ticks_ms(), t) > 1000:
            return None
    v = 0
    for _ in range(24):
        hx_sck.value(1)
        hx_sck.value(0)
        v = (v << 1) | hx_dt.value()
    hx_sck.value(1)                      # พัลส์ที่ 25 = เลือกช่อง A เกน 128
    hx_sck.value(0)
    if v & 0x800000:
        v -= 0x1000000
    return v

def hx_avg(n=5):
    s, k = 0, 0
    for _ in range(n):
        r = hx_raw()
        if r is not None:
            s += r
            k += 1
    return s // k if k else 0

def read_weight():
    global hx_offset
    if hx_offset is None:
        hx_offset = hx_avg(15)           # ตั้งศูนย์ครั้งแรก
    return round((hx_avg(5) - hx_offset) / HX_SCALE, 1)

def tof_read():
    i2c.writeto_mem(0x29, 0x00, b'\x01')      # สั่งวัด 1 ครั้ง
    t = time.ticks_ms()
    while (i2c.readfrom_mem(0x29, 0x13, 1)[0] & 0x07) == 0:
        if time.ticks_diff(time.ticks_ms(), t) > 300:
            return -1
        time.sleep_ms(5)
    d = i2c.readfrom_mem(0x29, 0x1E, 2)
    i2c.writeto_mem(0x29, 0x0B, b'\x01')      # ล้างสถานะ
    return d[0] << 8 | d[1]

def mlx_temp(reg):
    d = i2c.readfrom_mem(0x5A, reg, 3)
    return round((d[0] | d[1] << 8) * 0.02 - 273.15, 1)

def pulse_read(sec=3):
    vals = []
    t0 = time.ticks_ms()
    while time.ticks_diff(time.ticks_ms(), t0) < sec * 1000:
        wr = i2c.readfrom_mem(0x57, 0x04, 1)[0]
        rd = i2c.readfrom_mem(0x57, 0x06, 1)[0]
        for _ in range((wr - rd) & 0x1F):
            d = i2c.readfrom_mem(0x57, 0x07, 6)
            vals.append((d[3] << 16 | d[4] << 8 | d[5]) & 0x3FFFF)
        time.sleep_ms(20)
    if len(vals) < 20:
        return 0, 0
    ir = sum(vals) // len(vals)
    if ir < 50000:                     # ไม่มีนิ้ววางอยู่
        return ir, 0
    sm = [sum(vals[i:i + 8]) / 8 for i in range(len(vals) - 7)]
    avg = sum(sm) / len(sm)
    gap = (max(sm) - min(sm)) * 0.1
    beats, up = [], sm[0] > avg
    for i, v in enumerate(sm):
        if not up and v > avg + gap:
            beats.append(i)              # จุดที่คลื่นขึ้น = หัวใจเต้น 1 ครั้ง
            up = True
        elif up and v < avg - gap:
            up = False
    if len(beats) < 2:
        return ir, 0
    fs = len(vals) / sec                 # จำนวนจุดต่อวินาทีที่อ่านได้จริง
    return ir, int((len(beats) - 1) * 60 * fs / (beats[-1] - beats[0]))

