def eeg_band(buf, lo, hi):
    p = 0.0
    for k in range(1, EEG_N // 2):
        f = k * EEG_FS / EEG_N
        if lo <= f <= hi:
            re_ = im = 0.0
            for n in range(EEG_N):
                j = (k * n) % EEG_N
                re_ += buf[n] * EEG_COS[j]
                im += buf[n] * EEG_SIN[j]
            p += math.sqrt(re_ * re_ + im * im)
    return round(p, 2)

def eeg_read():
    b1, b2 = [], []
    step = 1000000 // EEG_FS
    for i in range(EEG_N):
        t = time.ticks_us()
        b1.append(eeg_a1.read_u16() * 3.3 / 65535 - 1.65)   # ลบค่ากลาง (DC offset)
        b2.append(eeg_a2.read_u16() * 3.3 / 65535 - 1.65)
        while time.ticks_diff(time.ticks_us(), t) < step:
            pass
    return eeg_band(b1, 8, 13), eeg_band(b1, 13, 30), eeg_band(b2, 8, 13), eeg_band(b2, 13, 30)

def tcs_read():
    d = i2c.readfrom_mem(0x29, 0xB4, 8)
    c, r, g, b = [d[i] | d[i + 1] << 8 for i in (0, 2, 4, 6)]
    if c == 0:
        return 0, 0, 0, 0
    return min(255, r * 255 // c), min(255, g * 255 // c), min(255, b * 255 // c), c
